def handler(context):
    # Emitted rather than dropped so every company is accounted for.
    def s(key):
        v = context.get_input(key)
        return "" if v is None else str(v).strip()

    return {"company_name": s("company_name"), "domain": s("domain"),
            "people_found": 0, "skipped_reason": s("reason")}
